import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Access to shared content","description":"Access restrictions for form, view, and portal links in ApptiveGrid.","frontmatter":{"title":"Access to shared content","description":"Access restrictions for form, view, and portal links in ApptiveGrid."},"headers":[],"relativePath":"en/zusammenarbeit/zugriff-beschraenken.md","filePath":"en/zusammenarbeit/zugriff-beschraenken.md","lastUpdated":1787812823000}'),o={name:"en/zusammenarbeit/zugriff-beschraenken.md"};function r(i,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="access-to-shared-content" tabindex="-1">Access to shared content <a class="header-anchor" href="#access-to-shared-content" aria-label="Permalink to &quot;Access to shared content&quot;">​</a></h1><p>Every shared link in ApptiveGrid is <strong>reachable by default by anyone who has the link</strong>. If you want to restrict access, you have to set that up explicitly.</p><div class="danger custom-block"><p class="custom-block-title">The most important point first</p><p>A share link isn&#39;t guessable, but it&#39;s unprotected. If it gets forwarded, copied into a chat, or quoted in an email, it keeps working there too.</p><p>Treat an unrestricted link like a publication.</p></div><h2 id="two-different-models" tabindex="-1">Two different models <a class="header-anchor" href="#two-different-models" aria-label="Permalink to &quot;Two different models&quot;">​</a></h2><p>ApptiveGrid has <strong>two separate restriction models</strong>. Which one applies depends on what you&#39;re sharing. This is the most common source of confusion in this area.</p><table tabindex="0"><thead><tr><th>You&#39;re sharing …</th><th>Model</th><th>Dialog</th></tr></thead><tbody><tr><td><strong>Form</strong></td><td>Who may access — by account</td><td><em>Set access restrictions</em></td></tr><tr><td><strong>View</strong> or <strong>page/portal</strong></td><td>Username and password</td><td><em>Set access permissions</em></td></tr></tbody></table><p>The two models <strong>can&#39;t be mixed</strong>. A form link doesn&#39;t know about a password, and a view link doesn&#39;t know about account checks.</p><hr><h2 id="forms-access-by-account" tabindex="-1">Forms: access by account <a class="header-anchor" href="#forms-access-by-account" aria-label="Permalink to &quot;Forms: access by account&quot;">​</a></h2><p>In a form&#39;s share dialog, <strong>Set restrictions</strong> leads to the <em>Set access restrictions</em> dialog, with the question <em>Define who can access the form via this link.</em></p><p>Three levels:</p><h3 id="anyone" tabindex="-1">Anyone <a class="header-anchor" href="#anyone" aria-label="Permalink to &quot;Anyone&quot;">​</a></h3><blockquote><p><em>Anyone with this link can access it.</em></p></blockquote><p>No sign-in required. The default.</p><p><strong>Suited for:</strong> public sign-ups, contact forms, surveys, feedback from customers.</p><h3 id="any-registered-user" tabindex="-1">Any registered user <a class="header-anchor" href="#any-registered-user" aria-label="Permalink to &quot;Any registered user&quot;">​</a></h3><blockquote><p><em>Only registered users can access it with this link.</em></p></blockquote><p>The person needs an ApptiveGrid account and must be signed in — but does <strong>not</strong> need to be a member of your Space.</p><p><strong>Suited for:</strong> forms where you need a traceable identity, but the people filling it in don&#39;t belong to the Space.</p><div class="warning custom-block"><p class="custom-block-title">This is a low bar</p><p>Anyone can create an ApptiveGrid account. This level ensures someone is <em>signed in</em> — not that it&#39;s the <em>right</em> person. It&#39;s not enough for confidential data.</p></div><h3 id="anyone-in-this-space" tabindex="-1">Anyone in this Space <a class="header-anchor" href="#anyone-in-this-space" aria-label="Permalink to &quot;Anyone in this Space&quot;">​</a></h3><blockquote><p><em>Only people invited to this Space can access it.</em></p></blockquote><p>The strictest level. Only people with a role in this Space.</p><p><strong>Suited for:</strong> internal forms — vacation requests, incident reports, internal data entry.</p><div class="tip custom-block"><p class="custom-block-title">Any role is enough</p><p>Even the <em>Read only</em> role is enough to fill in a form restricted this way. You don&#39;t need to give anyone editing rights just so they can submit a form — and doing it this way doesn&#39;t consume a <a href="/en/zusammenarbeit/sitzplaetze">seat</a> either.</p></div><hr><h2 id="views-and-portals-username-and-password" tabindex="-1">Views and portals: username and password <a class="header-anchor" href="#views-and-portals-username-and-password" aria-label="Permalink to &quot;Views and portals: username and password&quot;">​</a></h2><p>When sharing a view, or publishing a page, <strong>Set restrictions</strong> leads to the <em>Set access permissions</em> dialog, with the text <em>Define who has access</em>.</p><p>Two levels:</p><h3 id="everyone" tabindex="-1">Everyone <a class="header-anchor" href="#everyone" aria-label="Permalink to &quot;Everyone&quot;">​</a></h3><blockquote><p><em>Anyone with the link can access it</em></p></blockquote><p>The default. No protection beyond the link.</p><h3 id="with-credentials" tabindex="-1">With credentials <a class="header-anchor" href="#with-credentials" aria-label="Permalink to &quot;With credentials&quot;">​</a></h3><blockquote><p><em>Access only with username and password</em></p></blockquote><p>You set a <strong>username</strong>/<strong>password</strong> pair. A sign-in prompt appears when the link is opened:</p><blockquote><p><strong>Welcome!</strong><em>Let us unlock this view. Enter the credentials below.</em></p></blockquote><p><strong>Username</strong> and <strong>password</strong> are entered there and confirmed with <strong>Login</strong>. If the details are wrong, you&#39;ll see <em>Please check username and password</em>; if they&#39;re missing entirely: <em>Username is required</em> or <em>Password is required</em>.</p><p>These credentials have <strong>nothing to do with ApptiveGrid accounts</strong>. It&#39;s a standalone pair that only applies to this link. Recipients don&#39;t need an account.</p><div class="danger custom-block"><p class="custom-block-title">Credentials are only visible once</p><p>After saving, ApptiveGrid confirms with <em>Permissions updated</em> and explicitly points out:</p><blockquote><p><em>For security reasons, it&#39;s not possible to view the username and password later. However, you can reset them at any time.</em></p></blockquote><p><strong>Note the credentials down somewhere safe immediately.</strong> If they get lost, you&#39;ll need to set new ones and send them to all recipients again.</p></div><div class="tip custom-block"><p class="custom-block-title">One password per audience</p><p>Via <em>Add link</em>, create several links to the same view and give each its own credentials. That way you can revoke access for one group without having to send a new password to everyone else.</p></div><hr><h2 id="what-a-view-s-filter-does-—-and-doesn-t-do" tabindex="-1">What a view&#39;s filter does — and doesn&#39;t do <a class="header-anchor" href="#what-a-view-s-filter-does-—-and-doesn-t-do" aria-label="Permalink to &quot;What a view&#39;s filter does — and doesn&#39;t do&quot;">​</a></h2><p>When sharing a view, recipients only see what&#39;s visible in that view. Filters and hidden columns take effect as well.</p><div class="warning custom-block"><p class="custom-block-title">Filters are a visual screen, not access control</p><p>For genuinely confidential data, don&#39;t rely on filters and hidden columns alone. Combine them with an access restriction.</p><p>For true separation, the cleanest solution is to not put sensitive data in the same Grid in the first place.</p></div><hr><h2 id="choosing-the-right-level" tabindex="-1">Choosing the right level <a class="header-anchor" href="#choosing-the-right-level" aria-label="Permalink to &quot;Choosing the right level&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Recommendation</th></tr></thead><tbody><tr><td>Public sign-up form</td><td>Form, <strong>Anyone</strong></td></tr><tr><td>Customer feedback via QR code</td><td>Form, <strong>Anyone</strong></td></tr><tr><td>Internal form for the team</td><td>Form, <strong>Anyone in this Space</strong></td></tr><tr><td>Status overview for a customer</td><td>View, <strong>With credentials</strong></td></tr><tr><td>Public portal</td><td>Page, <strong>Everyone</strong></td></tr><tr><td>Portal for partners only</td><td>Page, <strong>With credentials</strong></td></tr><tr><td>Personal or confidential data</td><td>Don&#39;t share via link — <a href="/en/zusammenarbeit/personen-einladen">invite</a> people to the Space instead</td></tr></tbody></table><h2 id="check-regularly" tabindex="-1">Check regularly <a class="header-anchor" href="#check-regularly" aria-label="Permalink to &quot;Check regularly&quot;">​</a></h2><p>Shared links get forgotten. The <a href="/en/zusammenarbeit/externe-links">External links at a glance</a> page lists <strong>all</strong> external access points of a Space in one place: form links, view links, portals, Flow starts, and invitations.</p><div class="tip custom-block"><p class="custom-block-title">Make it part of your routine</p><p>Review this list at regular intervals and remove what&#39;s no longer needed — especially after finished projects, ended campaigns, and personnel changes.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/externe-links">External links at a glance</a></li><li><a href="/en/zusammenarbeit/personen-einladen">Inviting people</a></li><li><a href="/en/zusammenarbeit/rollen">Roles</a></li><li><a href="/en/formulare/formular-teilen">Sharing a form</a></li></ul>',52)])])}const u=t(o,[["render",r]]);export{m as __pageData,u as default};
